import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/checklist.dart';
const templates={'New pet home':['Prepare a quiet resting area','Set up food and water stations','Prepare safe toys and enrichment','Store veterinarian and emergency contacts','Review household hazards'],'First week':['Keep routines calm and predictable','Introduce rooms gradually','Record questions for the veterinarian','Practice short positive-reinforcement sessions'],'Grooming preparation':['Gather appropriate grooming supplies','Choose a calm, comfortable space','Introduce tools gradually','Plan breaks and positive rewards'],'Travel preparation':['Confirm pet-friendly transport arrangements','Prepare food, water and familiar items','Save veterinary contact information','Review destination and carrier requirements'],'Senior pet comfort':['Review home access and resting areas','Keep pathways clear','Record observations for the next vet visit','Check that contact details are current']};
class ChecklistsScreen extends ConsumerWidget{const ChecklistsScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final c=ref.watch(appControllerProvider),pet=c.selectedPet;final lists=c.items('checklists').map((e)=>Checklist.fromMap(e)).toList();return Scaffold(appBar:AppBar(title:const Text('Care checklists')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Simple, editable checklists for everyday transitions.'),const SizedBox(height:12),...templates.entries.map((entry){final matches=lists.where((e)=>e.title==entry.key&&e.petId==pet?.id).toList();final existing=matches.isEmpty?null:matches.first;return Card(child:ListTile(leading:const Icon(Icons.checklist,color:Color(0xFF39845A)),title:Text(entry.key),subtitle:Text('${existing?.items.where((i)=>i.state=='done').length??0} / ${existing?.items.length??entry.value.length} complete'),trailing:const Icon(Icons.chevron_right),onTap:()async{final checklist=existing??Checklist(id:DateTime.now().microsecondsSinceEpoch.toString(),title:entry.key,category:entry.key,petId:pet?.id,items:entry.value.asMap().entries.map((e)=>ChecklistItem(id:'${e.key}',title:e.value)).toList());if(existing==null)await c.save('checklists',checklist.toMap());if(context.mounted)Navigator.push(context,MaterialPageRoute(builder:(_)=>ChecklistDetail(checklist:checklist)));}));})]));}}
class ChecklistDetail extends ConsumerStatefulWidget{const ChecklistDetail({super.key,required this.checklist});final Checklist checklist;@override ConsumerState<ChecklistDetail> createState()=>_ChecklistDetailState();}
class _ChecklistDetailState extends ConsumerState<ChecklistDetail>{late List<ChecklistItem> items;@override void initState(){super.initState();items=[...widget.checklist.items];}Future<void> persist()async{final next=Checklist(id:widget.checklist.id,title:widget.checklist.title,category:widget.checklist.category,petId:widget.checklist.petId,species:widget.checklist.species,items:items);await ref.read(appControllerProvider).save('checklists',next.toMap());}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.checklist.title),actions:[IconButton(onPressed:()async{setState(()=>items=items.map((e)=>ChecklistItem(id:e.id,title:e.title,note:e.note)).toList());await persist();},icon:const Icon(Icons.refresh),tooltip:'Reset checklist')]),body:ListView(padding:const EdgeInsets.all(16),children:[...items.asMap().entries.map((entry)=>CheckboxListTile(value:entry.value.state=='done',title:Text(entry.value.title),onChanged:(v)async{setState(()=>items[entry.key]=ChecklistItem(id:entry.value.id,title:entry.value.title,note:entry.value.note,state:v==true?'done':'todo'));await persist();})),OutlinedButton.icon(onPressed:()async{final controller=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Add checklist item'),content:TextField(controller:controller,decoration:const InputDecoration(labelText:'Item')),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Add'))]));if(ok==true&&controller.text.trim().isNotEmpty){setState(()=>items.add(ChecklistItem(id:DateTime.now().microsecondsSinceEpoch.toString(),title:controller.text.trim())));await persist();}},icon:const Icon(Icons.add),label:const Text('Add custom item'))]));}
